import{_ as t,o as r,c as o,a3 as a}from"./chunks/framework.D1iekJsc.js";const p=JSON.parse('{"title":"OpenRouter","description":"OpenRouter 免費模型：官網 Free Models 合集、:free 文本/視覺列表、拿 Key 與限額，以及在 MiniTavern 中的填法。","frontmatter":{"title":"OpenRouter","description":"OpenRouter 免費模型：官網 Free Models 合集、:free 文本/視覺列表、拿 Key 與限額，以及在 MiniTavern 中的填法。","head":[["meta",{"name":"keywords","content":"酒館,AI酒館,Ai酒館,迷你酒館,超迷你酒館,MiniTavern,AI夥伴,AI朋友,Ai本地聊天,Silly Tavern,SillyTavern,手機玩Silly Tavern,Silly Tavern手機版,Silly Tavern安卓,Silly Tavern蘋果,AI角色扮演,角色卡,角色扮演,AI聊天,手機AI,離線AI,AI劇情,本地大模型,本地模型,Ollama,LM Studio,世界書,正則,BYOK,使用手冊,教學,character card,AI roleplay,AI companion"}],["meta",{"property":"og:title","content":"OpenRouter · MiniTavern Docs"}],["meta",{"property":"og:description","content":"OpenRouter 免費模型：官網 Free Models 合集、:free 文本/視覺列表、拿 Key 與限額，以及在 MiniTavern 中的填法。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/zh-TW/free-cloud/openrouter"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/zh-TW/free-cloud/openrouter"}]]},"headers":[],"relativePath":"zh-TW/free-cloud/openrouter.md","filePath":"zh-TW/free-cloud/openrouter.md","lastUpdated":1787224147000}'),d={name:"zh-TW/free-cloud/openrouter.md"};function n(i,e,l,c,s,h){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="openrouter" tabindex="-1">OpenRouter <a class="header-anchor" href="#openrouter" aria-label="Permalink to &quot;OpenRouter&quot;">​</a></h1><p>全球模型聚合網關：一個 API Key 可調用大量模型。其中部分為 <strong>免費池</strong>（模型 ID 常以 <code>:free</code> 結尾，或官方標 Free），適合個人試用、對比開源模型與低頻角色扮演。官方合集：<a href="https://openrouter.ai/collections/free-models" target="_blank" rel="noreferrer">Free Models</a>；第三方彙總可參考 <a href="https://openairouter.net/free-models" target="_blank" rel="noreferrer">openairouter.net/free-models</a>（非官方，以 OpenRouter 控制台為準）。</p><blockquote><p>免費名單、RPM / 日請求上限會變。<strong>以 <a href="https://openrouter.ai/models?q=free" target="_blank" rel="noreferrer">openrouter.ai/models</a> 與賬戶頁為準</strong>。</p></blockquote><h2 id="官網與入口" tabindex="-1">官網與入口 <a class="header-anchor" href="#官網與入口" aria-label="Permalink to &quot;官網與入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>資源</th><th>地址</th></tr></thead><tbody><tr><td>官網</td><td><a href="https://openrouter.ai/" target="_blank" rel="noreferrer">openrouter.ai</a></td></tr><tr><td>API Key</td><td><a href="https://openrouter.ai/keys" target="_blank" rel="noreferrer">openrouter.ai/keys</a></td></tr><tr><td>Free Models 合集</td><td><a href="https://openrouter.ai/collections/free-models" target="_blank" rel="noreferrer">openrouter.ai/collections/free-models</a></td></tr><tr><td>模型廣場（篩 Free）</td><td><a href="https://openrouter.ai/models?q=free" target="_blank" rel="noreferrer">openrouter.ai/models?q=free</a></td></tr><tr><td>社區彙總（第三方）</td><td><a href="https://openairouter.net/free-models" target="_blank" rel="noreferrer">openairouter.net/free-models</a></td></tr><tr><td>API Base URL</td><td><code>https://openrouter.ai/api/v1</code>（MiniTavern 選 <strong>OpenRouter</strong> 時一般無需手填）</td></tr></tbody></table><h2 id="免費怎麼獲取" tabindex="-1">免費怎麼獲取 <a class="header-anchor" href="#免費怎麼獲取" aria-label="Permalink to &quot;免費怎麼獲取&quot;">​</a></h2><ol><li>打開 <a href="https://openrouter.ai/keys" target="_blank" rel="noreferrer">openrouter.ai/keys</a> 註冊並創建 Key（通常 <strong>無需信用卡</strong>）。</li><li>在 <a href="https://openrouter.ai/collections/free-models" target="_blank" rel="noreferrer">Free Models</a> 或模型廣場複製 <strong>Model ID</strong>（注意 <code>:free</code> 後綴）。</li><li>在 MiniTavern 選平臺 <strong>OpenRouter</strong>，粘貼 Key，模型填該 ID。</li></ol><table tabindex="0"><thead><tr><th>項目</th><th>說明</th></tr></thead><tbody><tr><td>免費方式</td><td>ID 含 <code>:free</code>，或合集中標價 <code>$0</code> 的模型；也可用自動路由 <code>openrouter/free</code></td></tr><tr><td>限速參考</td><td>常見約 <strong>20 RPM / 約 50 次/天</strong>；一次性充值約 <strong>$10+</strong> 後，免費模型日限額可升至約 <strong>1000 次/天</strong>（規則以官方為準）</td></tr><tr><td>綁卡</td><td>免費檔通常不需要；充值僅用於提高限額或調用付費模型</td></tr><tr><td>隱私</td><td>部分免費上游可能用提示詞改進模型；可在 OpenRouter 設置查看隱私選項。Poolside Laguna 等免費檔文檔寫明可能用於訓練</td></tr></tbody></table><h2 id="模型列表" tabindex="-1">模型列表 <a class="header-anchor" href="#模型列表" aria-label="Permalink to &quot;模型列表&quot;">​</a></h2><p>下列為合集與公開彙總中的常見 <strong>文本 / 視覺</strong> ID（約 2026-08）；<strong>實際以官網為準</strong>。ID <strong>大小寫敏感</strong>，<code>:free</code> 不可省略（除非該條目本身無此後綴）。</p><h3 id="文本-·-自動路由" tabindex="-1">文本 · 自動路由 <a class="header-anchor" href="#文本-·-自動路由" aria-label="Permalink to &quot;文本 · 自動路由&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模型 ID</th><th>說明</th></tr></thead><tbody><tr><td><code>openrouter/free</code></td><td>按請求自動挑選可用免費模型；上手最快，質量不固定</td></tr></tbody></table><h3 id="文本-·-通用對話" tabindex="-1">文本 · 通用對話 <a class="header-anchor" href="#文本-·-通用對話" aria-label="Permalink to &quot;文本 · 通用對話&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模型 ID</th><th>說明</th></tr></thead><tbody><tr><td><code>meta-llama/llama-3.3-70b-instruct:free</code></td><td>綜合向、多語言</td></tr><tr><td><code>meta-llama/llama-3.2-3b-instruct:free</code></td><td>輕量</td></tr><tr><td><code>openai/gpt-oss-20b:free</code> / <code>openai/gpt-oss-120b:free</code></td><td>OpenAI 開源權重 MoE</td></tr><tr><td><code>google/gemma-3-27b-it:free</code> / <code>google/gemma-3-12b-it:free</code> / <code>google/gemma-3-4b-it:free</code></td><td>Gemma 3 系列</td></tr><tr><td><code>google/gemma-4-31b-it:free</code> / <code>google/gemma-4-26b-a4b-it:free</code></td><td>Gemma 4（部分支持視覺）</td></tr><tr><td><code>google/gemma-3n-e4b-it:free</code> / <code>google/gemma-3n-e2b-it:free</code></td><td>端側向輕量</td></tr><tr><td><code>qwen/qwen3-next-80b-a3b-instruct:free</code></td><td>Qwen3 對話</td></tr><tr><td><code>z-ai/glm-4.5-air:free</code></td><td>GLM 輕量，中文友好</td></tr><tr><td><code>minimax/minimax-m2.5:free</code></td><td>MiniMax</td></tr><tr><td><code>nousresearch/hermes-3-llama-3.1-405b:free</code></td><td>Hermes 3</td></tr><tr><td><code>arcee-ai/trinity-large-preview:free</code></td><td>Arcee Trinity Large Preview</td></tr><tr><td><code>openrouter/elephant-alpha</code></td><td>OpenRouter 託管文本模型（合集/廣場若標 Free）</td></tr><tr><td><code>cognitivecomputations/dolphin-mistral-24b-venice-edition:free</code></td><td>Venice Uncensored 變體（內容尺度自行把握）</td></tr></tbody></table><h3 id="文本-·-推理-agent-編碼" tabindex="-1">文本 · 推理 / Agent / 編碼 <a class="header-anchor" href="#文本-·-推理-agent-編碼" aria-label="Permalink to &quot;文本 · 推理 / Agent / 編碼&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模型 ID</th><th>說明</th></tr></thead><tbody><tr><td><code>qwen/qwen3-coder:free</code></td><td>Qwen3 Coder，代碼向</td></tr><tr><td><code>nvidia/nemotron-3-ultra:free</code>（或合集當前 ID）</td><td>Nemotron 3 Ultra，長上下文 Agent</td></tr><tr><td><code>nvidia/nemotron-3.5-lightning:free</code></td><td>高吞吐 Agent</td></tr><tr><td><code>nvidia/nemotron-3-super-120b-a12b:free</code></td><td>Nemotron 3 Super</td></tr><tr><td><code>nvidia/nemotron-3-nano-30b-a3b:free</code> / <code>nvidia/nemotron-nano-9b-v2:free</code></td><td>Nano 系列</td></tr><tr><td><code>poolside/laguna-s-2.1:free</code> / <code>poolside/laguna-xs-2.1:free</code>（以廣場 ID 為準）</td><td>Poolside 編碼 Agent；免費檔可能用於訓練</td></tr><tr><td><code>cohere/north-mini-code:free</code>（以廣場為準）</td><td>Cohere North 編碼</td></tr><tr><td><code>liquid/lfm-2.5-1.2b-instruct:free</code> / <code>liquid/lfm-2.5-1.2b-thinking:free</code></td><td>Liquid 輕量</td></tr><tr><td><code>dots-studio/dots3-note-preview:free</code>（以廣場為準）</td><td>Dots3-Note Preview</td></tr></tbody></table><p>合集按用量排序會變；編程向亦可在 <a href="https://openrouter.ai/collections/coding" target="_blank" rel="noreferrer">Coding</a> 中再篩 Free。</p><h3 id="文本-·-視覺-多模態輸入" tabindex="-1">文本 · 視覺（多模態輸入） <a class="header-anchor" href="#文本-·-視覺-多模態輸入" aria-label="Permalink to &quot;文本 · 視覺（多模態輸入）&quot;">​</a></h3><p>聊天主模型若支持視覺，可在 App 開啟識圖 / 多模態直傳時試用：</p><table tabindex="0"><thead><tr><th>模型 ID</th><th>說明</th></tr></thead><tbody><tr><td><code>google/gemma-3-27b-it:free</code> 等 Gemma 3/4</td><td>文 + 圖輸入</td></tr><tr><td><code>nvidia/nemotron-nano-12b-v2-vl:free</code></td><td>視覺 / 文檔</td></tr><tr><td><code>nvidia/nemotron-3-nano-omni:free</code>（以廣場為準）</td><td>多模態感知</td></tr><tr><td><code>meta-llama/llama-guard-4-12b:free</code></td><td>安全分類向，一般不當聊天主模型</td></tr></tbody></table><h3 id="圖片-視頻" tabindex="-1">圖片 / 視頻 <a class="header-anchor" href="#圖片-視頻" aria-label="Permalink to &quot;圖片 / 視頻&quot;">​</a></h3><ul><li><strong>生圖</strong>：見 OpenRouter <a href="https://openrouter.ai/collections/image-models" target="_blank" rel="noreferrer">Image Models</a>；是否免費以模型頁定價為準。MiniTavern 生圖連接可選 <strong>OpenRouter</strong>。</li><li><strong>視頻</strong>：見 <a href="https://openrouter.ai/collections/video-models" target="_blank" rel="noreferrer">Video Models</a>；App <strong>無內置視頻入口</strong>。</li><li>第三方列表中的 Lyria 等偏音樂生成，與聊天 / 生圖無關，勿當對話模型。</li></ul><h2 id="在-minitavern-裡怎麼填" tabindex="-1">在 MiniTavern 裡怎麼填 <a class="header-anchor" href="#在-minitavern-裡怎麼填" aria-label="Permalink to &quot;在 MiniTavern 裡怎麼填&quot;">​</a></h2><p>通用步驟見 <a href="/ultra_guides/zh-TW/manual/model-link">模型連接</a>。</p><h3 id="聊天" tabindex="-1">聊天 <a class="header-anchor" href="#聊天" aria-label="Permalink to &quot;聊天&quot;">​</a></h3><p>路徑：<strong>設置 → 模型 → 模型連接 → 新建</strong></p><ol><li>平臺選 <strong>OpenRouter</strong>（預設 Base URL）</li><li>粘貼 API Key</li><li>模型 ID 填例如 <code>meta-llama/llama-3.3-70b-instruct:free</code>，或 <code>openrouter/free</code></li><li><strong>測試</strong> → 成功後設為默認</li></ol><p>也可選 <strong>自定義 (OpenAI)</strong>，Base URL <code>https://openrouter.ai/api/v1</code>，效果類似；優先用 App 預設。</p><h3 id="生圖" tabindex="-1">生圖 <a class="header-anchor" href="#生圖" aria-label="Permalink to &quot;生圖&quot;">​</a></h3><p>路徑：<strong>設置 → 生圖 → 生圖連接</strong> → 平臺 <strong>OpenRouter</strong>，模型選廣場中支持圖像且免費（或可接受計費）的 ID。更穩的免費生圖見 <a href="/ultra_guides/zh-TW/free-cloud/agnes-ai">Agnes AI</a>、<a href="/ultra_guides/zh-TW/free-cloud/aihubmix">AIHubMix</a>。</p><h3 id="排錯" tabindex="-1">排錯 <a class="header-anchor" href="#排錯" aria-label="Permalink to &quot;排錯&quot;">​</a></h3><table tabindex="0"><thead><tr><th>現象</th><th>處理</th></tr></thead><tbody><tr><td><code>HTTP 429</code> / <code>Provider returned error</code></td><td>上游免費池滿或限流：換其它 <code>:free</code>、稍後再試，或 <a href="https://openrouter.ai/settings/integrations" target="_blank" rel="noreferrer">BYOK</a></td></tr><tr><td>國內訪問失敗</td><td>官方 API 可能需代理；或改用國內直連廠商 / <a href="/ultra_guides/zh-TW/free-cloud/aihubmix">AIHubMix</a> 等</td></tr><tr><td>模型 404 / unavailable</td><td>該 <code>:free</code> 已下線：到合集重新複製 ID</td></tr></tbody></table><p>更多見 <a href="/ultra_guides/zh-TW/manual/errors">錯誤排錯</a>。</p><h2 id="相關章節" tabindex="-1">相關章節 <a class="header-anchor" href="#相關章節" aria-label="Permalink to &quot;相關章節&quot;">​</a></h2><ul><li><a href="/ultra_guides/zh-TW/free-cloud/">免費雲端總覽</a></li><li><a href="/ultra_guides/zh-TW/free-cloud/freellm">FreeLLM 目錄</a> — 更多免費廠商索引</li><li><a href="/ultra_guides/zh-TW/free-cloud/aihubmix">AIHubMix</a> — 補貼型 <code>*-free</code>（含部分閉源鏡像）</li><li><a href="/ultra_guides/zh-TW/free-cloud/agnes-ai">Agnes AI</a> · <a href="/ultra_guides/zh-TW/free-cloud/opencode-zen">OpenCode Zen</a></li><li><a href="/ultra_guides/zh-TW/manual/model-link">模型連接</a></li><li><a href="/ultra_guides/zh-TW/free-cloud/#免費生圖怎麼配">免費生圖</a></li></ul>',35)])])}const f=t(d,[["render",n]]);export{p as __pageData,f as default};
